const load = React.useCallback(async (nextQuery: string, retainResults: boolean) => {
  const id = ++requestId.current;
  setError('');
  setLoadState(retainResults ? 'refreshing' : 'loading');
  try {
    const nextRecords = await getRecords(nextQuery);
    if (id !== requestId.current) return;
    setRecords(nextRecords);
    setSelected((ids) => ids.filter((selectedId) => nextRecords.some((record) => record.id === selectedId)));
    setLoadState('ready');
  } catch (reason) {
    if (id !== requestId.current) return;
    setError(reason instanceof Error ? reason.message : 'The records could not be loaded.');
    setLoadState('failed');
  }
}, []);

function submitSearch(event: React.FormEvent) {
  event.preventDefault();
  const nextQuery = search.trim();
  setSelected([]);
  nextQuery === query ? void load(query, records.length > 0) : setQuery(nextQuery);
}

function clearSearch() {
  setSearch('');
  setSelected([]);
  query === '' ? void load('', records.length > 0) : setQuery('');
}

