{loadState === 'failed' && <Alert tone="critical" variant="raised" title={hasStaleResults ? 'Could not refresh records' : 'Could not load records'} action={<Button variant="secondary" onClick={() => void load(query, records.length > 0)}>Try again</Button>}>
