const form = useEditRecord<Workspace>({
  initialValue: workspace,
  validationMode: 'submit',
  validate: value => {
    const errors: Partial<Record<keyof Workspace, string>> = {};
    if (!value.name.trim()) errors.name = 'Enter a workspace name.';
    if (!value.email.trim()) errors.email = 'Enter a contact email.';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.email.trim())) errors.email = 'Enter a valid email address, such as name@example.com.';
    return errors;
  },
  save: async value => {
    try {
      const saved = await saveWorkspace({...value, name: value.name.trim(), email: value.email.trim(), description: value.description?.trim() ?? ''});
      onSaved(saved);
      return {ok: true, value: saved};
    } catch (error) {
      return {ok: false, error: messageFrom(error)};
    }
  },
  messages: {
    saving: 'Saving workspace settings…', saved: 'Workspace settings saved.',
    failed: 'Workspace settings could not be saved.', invalid: 'Check the highlighted fields and try again.',
    newerEdits: 'Your earlier changes were saved. Save again to keep your latest changes.',
  },
});

React.useEffect(() => {
