    if (!form.dirty || form.phase === 'submitting') return;
    event.preventDefault(); event.returnValue = '';
  };
  window.addEventListener('beforeunload', warn);
  return () => window.removeEventListener('beforeunload', warn);
}, [form.dirty, form.phase]);

const cancel = async () => {
  const mayLeave = await form.requestLeave('cancel', () => window.confirm('Discard your unsaved workspace changes?'));
  if (mayLeave) onCancel();
};

function App() {
