  React.useEffect(() => {
    let active = true; setLoadError('');
    getWorkspace().then(value => { if (active) setWorkspace(value); }).catch(error => { if (active) setLoadError(messageFrom(error)); });
    return () => { active = false; };
  }, [reloadKey]);
  if (loadError) return <main className="shell"><section className="page"><Alert tone="critical" variant="raised" title="Couldn’t load workspace" action={<Button variant="secondary" onClick={() => setReloadKey(key => key + 1)}>Try again</Button>}>{loadError}</Alert></section></main>;
  if (!workspace) return <main className="shell" aria-busy="true" aria-label="Loading workspace"><section className="page"><Skeleton shape="text" lines={2} width="54%" /><Skeleton className="loading-card" shape="block" height={300} /></section></main>;
