const collection = useAsyncCollection<ProjectRecord, string>({
  initialQuery: '',
  load: loadRecords,
  getKey: record => record.id,
  isFiltered: query => query !== '',
  // Selection survives searches; records selected outside the current results are listed below.
  selection: 'preserve',
  messages: {
    loading: 'Loading project records',
    refreshing: 'Refreshing project records',
