React.useEffect(() => {
  if (collection.phase === 'populated' || collection.phase === 'empty' || collection.phase === 'no-results') setShownQuery(collection.query);
}, [collection.phase, collection.query]);

const pendingSearch = React.useRef<number | undefined>(undefined);
