if (error && !pending) phase = 'failed';
else if (records === null) phase = 'loading';
else if (pending) phase = 'refreshing';
else if (records.length > 0) phase = 'populated';
else phase = settledQuery === INITIAL_QUERY ? 'empty' : 'no-results';

let status = '';
if (phase === 'loading' || phase === 'refreshing') status = '';
else if (phase === 'failed') status = records ? 'Could not refresh records. Showing earlier results.' : 'Could not load records.';
else if (phase === 'empty') status = 'No project records yet.';
else if (phase === 'no-results') status = `No records match “${settledQuery}”.`;
else status = settledQuery ? `${plural(visible.length, 'record')} match “${settledQuery}”.` : `${plural(visible.length, 'record')}.`;

{phase === 'failed' && (
