        {hiddenSelected.length > 0 && <Badge>{hiddenSelected.length} not in current results</Badge>}
        <Button size="sm" variant="ghost" onClick={() => setSelected(new Map())} disabled={selected.size === 0} style={{marginInlineStart: 'auto'}}>Clear selection</Button>
      </div>
      {hiddenSelected.length > 0 && (
