              </li>
            ))}
          </ul>
        </details>
      )}
    </CardContent>
  </Card>
)}

const nameCollator = new Intl.Collator(undefined, {numeric: true, sensitivity: 'base'});

/** Sorts a copy of the loaded results by name. Ties fall back to id so the order is stable across refreshes. */
function sortRecords(records: ProjectRecord[], order: SortOrder) {
  const direction = order === 'name-desc' ? -1 : 1;
  return [...records].sort((a, b) => direction * (nameCollator.compare(a.name, b.name) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)));
}

const load = React.useCallback(async (q: string) => {
  const id = ++latest.current;
  setLoading(true);
  setError(null);
  try {
    const result = await getRecords(q);
    if (id === latest.current) setRows(result);
  } catch (e) {
    if (id === latest.current) setError(e instanceof Error ? e.message : 'Request failed');
  } finally {
    if (id === latest.current) setLoading(false);
  }
}, []);

{error && (
  <Alert tone="critical" title="Couldn't load records" action={<Button size="sm" onClick={() => load(search)}>Try again</Button>}>
    {error}
  </Alert>
)}

// The Name header and this control share one sort. Sorting by ID from its header leaves the
// control on its placeholder, since none of its options describe that order.
const sortValue = !sort ? 'none' : sort.key === 'name' ? sort.direction : '';
const onSortValueChange = (value: string) =>
  setSort(value === 'ascending' || value === 'descending' ? {key: 'name', direction: value} : null);

empty={search ? (
  <EmptyState
    size="sm"
    announce
