{/* DataTable's count badge is aria-hidden, so announce the number here. */}
<p role="status" style={visuallyHidden}>
  {selected.length > 0 && `${selected.length} ${selected.length === 1 ? 'record' : 'records'} selected`}
</p>

const loadErrorMessage = (error: unknown) => error instanceof TypeError
  ? 'We couldn’t reach the server. Check your connection and try again.'
  : `We couldn’t load the workspace. ${error instanceof Error ? error.message : ''}`.trim();

function useWorkspace(initial?: Workspace) {
  const [attempt, setAttempt] = React.useState(0);
  const [load, setLoad] = React.useState<Load>({phase: 'loading'});
  React.useEffect(() => {
    let current = true;
    setLoad({phase: 'loading'});
    getWorkspace().then(
      workspace => { if (current) setLoad({phase: 'ready', workspace}); },
      error => { if (current) setLoad({phase: 'failed', error: loadErrorMessage(error)}); });
    return () => { current = false; };
  }, [attempt]);
  return {load: load.phase === 'loading' && initial ? {phase: 'ready' as const, workspace: initial, refreshing: true} : load, retry: () => setAttempt(n => n + 1)};
}

/** Focuses the view heading on arrival so keyboard and screen-reader users land at the new context. */
function useArrivalFocus(focus: boolean) {
  const ref = React.useRef<HTMLHeadingElement>(null);
  React.useEffect(() => { if (focus) ref.current?.focus(); }, [focus]);
  return ref;
}

function useDiscardConfirmation() {
  const resolver = React.useRef<((discard: boolean) => void) | null>(null);
  const [open, setOpen] = React.useState(false);
  const answer = (discard: boolean) => { resolver.current?.(discard); resolver.current = null; setOpen(false); };
  const confirm = () => new Promise<boolean>(resolve => { resolver.current = resolve; setOpen(true); });
  React.useEffect(() => () => resolver.current?.(false), []);
  const dialog = <Dialog open={open} onOpenChange={next => { if (!next) answer(false); }} size="sm"
    title="Discard unsaved changes?" description="Your changes to the workspace settings haven’t been saved."
    footer={<>
      <Button variant="secondary" onClick={() => answer(false)}>Keep editing</Button>
      <Button variant="danger" onClick={() => answer(true)}>Discard changes</Button>
    </>} />;
  return {confirm, dialog};
}

const validate = (value: SettingsDraft) => {
  const errors: Partial<Record<keyof SettingsDraft, string>> = {};
  if (!value.name.trim()) errors.name = 'Enter a workspace name.';
  if (!value.email.trim()) errors.email = 'Enter a contact email address.';
  else if (!EMAIL_PATTERN.test(value.email.trim())) errors.email = 'Enter an email address in the format name@example.com.';
  if (value.description.trim().length > DESCRIPTION_MAX_LENGTH) errors.description = `Shorten the description to ${DESCRIPTION_MAX_LENGTH} characters or fewer.`;
  return errors;
};
const save = async (draft: SettingsDraft): Promise<EditRecordResult<SettingsDraft>> => {
  try {
    return {ok: true, value: toDraft(await saveWorkspace({name: draft.name.trim(), email: draft.email.trim(), description: draft.description.trim()}))};
  } catch (error) {
    return {ok: false, error: error instanceof TypeError
      ? 'We couldn’t reach the server. Your changes are still here; try saving again.'
      : `We couldn’t save your changes. ${error instanceof Error ? error.message : ''} Your changes are still here; try saving again.`.replace(/\s+/g, ' ')};
  }
};

const requestLeave = React.useCallback<LeaveGuard>(async reason => {
  if (formRef.current.phase === 'submitting') { setLeaveBlocked('Wait for your changes to finish saving before leaving.'); return false; }
  setLeaveBlocked('');
  return formRef.current.requestLeave(reason, () => confirm());
}, []);
React.useEffect(() => { registerGuard(requestLeave); return () => registerGuard(null); }, [registerGuard, requestLeave]);
React.useEffect(() => { if (form.phase === 'saved') onSaved(form.baseline); }, [form.phase, form.baseline]);
React.useEffect(() => {
  if (!form.dirty && form.phase !== 'submitting') return;
  const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ''; };
  addEventListener('beforeunload', warn);
  return () => removeEventListener('beforeunload', warn);
}, [form.dirty, form.phase]);

const openSettings = () => { history.pushState(null, '', SETTINGS_HASH); pushedSettings.current = true; setView('settings'); };
/** Called once the settings form has agreed to leave (clean, or the person chose to discard). */
const leaveSettings = () => {
  if (pushedSettings.current) { pushedSettings.current = false; ignoreNextPop.current = true; history.back(); }
  else history.replaceState(null, '', location.pathname + location.search);
  showOverview();
};

React.useEffect(() => {
  const onPop = async () => {
    if (ignoreNextPop.current) { ignoreNextPop.current = false; return; }
    const next = viewFromLocation();
    if (viewRef.current === 'settings' && next !== 'settings' && guard.current) {
      // Browser Back already moved; restore the settings entry until the form agrees to leave.
      history.pushState(null, '', SETTINGS_HASH);
      if (!(await guard.current('back'))) return;
      ignoreNextPop.current = true; history.back();
      pushedSettings.current = false; showOverview();
      return;
    }
    pushedSettings.current = false;
    if (next === 'overview') showOverview(); else setView(next);
  };
  addEventListener('popstate', onPop);
  return () => removeEventListener('popstate', onPop);
}, []);

// Business validation, run on submit (not while typing).
function validate(draft: Draft): Errors {
  const errors: Errors = {};
  if (!draft.name.trim()) errors.name = 'Enter a workspace name';
  else if (draft.name.trim().length > 80) errors.name = 'Workspace name must be 80 characters or fewer';
  if (!draft.email.trim()) errors.email = 'Enter a contact email';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.email.trim())) errors.email = 'Enter an email address in the correct format, like name@example.com';
  if (draft.description.trim().length > DESCRIPTION_MAX) errors.description = `Description must be ${DESCRIPTION_MAX} characters or fewer`;
  return errors;
}

