const submit = async () => {
  if (pending.current) return; // reject duplicate activation
  const submitted = draftRef.current;
  const found = validate(submitted);
  setErrors(found);
  setSubmitCount(c => c + 1);
  if (Object.keys(found).length) { setPhase('invalid'); return; }
  pending.current = true;
  setFailure(null);
  setPhase('submitting');
  try {
    const value: Workspace = {...baseline, name: submitted.name.trim(), email: submitted.email.trim(), description: submitted.description.trim()};
    const saved = await saveWorkspace(value);
    setBaseline(saved);
    // Only adopt the canonical value if the person hasn't edited since submitting.
    if (sameDraft(draftRef.current, submitted)) setDraft(toDraft(saved));
    setPhase('saved');
  } catch (e) {
    setFailure(message(e));
    setPhase('failed');
  } finally {
    pending.current = false;
  }
};

